"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import Image from "next/image";

type StudentView = "home" | "jobs" | "wallet" | "bank" | "growth" | "room";
type Competency = { key: string; name: string; description: string; xp: number; color: string };
type Posting = { id: string; title: string; description: string; world: string; related_job_codes?: string[]; capacity: number; assigned_count: number; reward: number; duration_minutes: number; competency_rewards: Record<string, number>; submission_method: string; status: string };
type Application = { id: string; posting_id: string; title: string; world?: string; related_job_codes?: string[]; status: string; summary?: string; result_url?: string; fun_rating?: number; difficulty_rating?: number; completed_at?: string; evidence_review_status?: "not_reviewed" | "reviewed" | "revision_requested"; evidence_feedback?: string };
type Transaction = { id: number; transaction_type: string; cash_delta: number; savings_delta: number; cash_after: number; savings_after: number; created_at: string };
type BankRequest = { id: string; request_type: string; amount: number; status: string; requested_at?: string };
type BankQueue = { id: string; student_name: string; request_type: string; amount: number; requested_at: string };
type Badge = { key: string; name: string; description: string; icon: string; awarded_at: string };
type RoomItem = { key: string; name: string; slot: string; style: string; required: number; visual: string; unlocked: boolean; equipped: boolean };
type Seat = { id: string; code: string; name: string; type: string; rent: number; move_cost: number; available: boolean };
type CommunityGoal = { id?: string; title?: string; description?: string; target_amount?: number; current_amount?: number; min_donations?: number; qualified_students?: number; total_students?: number; status?: string };
type BasicJobTask = { id: string; key: string; title: string; description: string; proof_mode: "system" | "photo" | "result" | "peer" | "checklist" };
type BasicJobSubmission = { id: string; task_id: string; title: string; proof_mode: BasicJobTask["proof_mode"]; summary: string; evidence_url?: string; status: "pending_confirmation" | "confirmed" | "rejected"; submitted_at: string; reviewed_at?: string; verifier_name?: string };
type PeerReview = { id: string; student_name: string; task_title: string; summary: string; submitted_at: string };
type Classmate = { id: string; name: string; job?: string };
type TeacherJobSubmission = { id: string; student_name: string; student_number: number; posting_title: string; status: string; summary?: string; result_url?: string; fun_rating?: number; difficulty_rating?: number; applied_at: string; completed_at?: string; evidence_review_status: "not_reviewed" | "reviewed" | "revision_requested"; evidence_feedback?: string };
type StudentData = {
  student_id: string; display_name: string; student_number: number; first_login: boolean; account_status: string;
  basic_job: string | null; job_world?: string | null; cash: number; savings: number; housing_name: string | null;
  growth_stage: number; basic_job_tasks_completed: number; jobs_completed: number; first_salary_received: boolean;
  first_saving_completed: boolean; saving_goal_reached: boolean; donation_count: number; total_donation: number;
  feature_unlocks: string[]; competencies: Competency[]; postings: Posting[]; applications: Application[];
  transactions: Transaction[]; bank_requests: BankRequest[]; bank_queue: BankQueue[]; badges: Badge[];
  career_experiences: { job: string; count: number; kind: string }[];
  avatar: { hair: string; background: string; displayed_badge_key: string | null };
  room_items: RoomItem[]; seats: Seat[]; community_goal: CommunityGoal;
  basic_job_task_catalog: BasicJobTask[]; basic_job_submissions: BasicJobSubmission[];
  peer_review_queue: PeerReview[]; classmates: Classmate[];
};
type TeacherData = {
  teacher_id: string; display_name: string; class_code: string; class_name: string; grade?: number; section?: number;
  active_week: { id?: string; week_number?: number; status?: string; starts_on?: string };
  stats: { students: number; participating: number; completed: number; exceptions: number };
  students: { id: string; name: string; number: number; job?: string; cash: number; savings: number; tasks: number; jobs_completed: number }[];
  postings: { id: string; title: string; capacity: number; assigned: number; completed: number; status: string }[];
  bank_requests: { id: string; student_name: string; request_type: string; amount: number; status: string }[];
  exceptions: { id: string; type: string; title: string; detail: string; student_name?: string; created_at: string }[];
  community_goal: { id?: string; title?: string; description?: string; target_amount?: number; current_amount?: number; min_donations?: number; status?: string };
  job_catalog: { code: string; title: string; description?: string; world: string; salary: number }[];
  templates: { id: string; title: string; description?: string; world: string; world_key?: string; related_job_codes?: string[]; capacity: number; reward: number; duration_minutes: number; competency_rewards?: Record<string, number>; submission_method?: string; repeatable?: boolean; custom?: boolean }[];
  seat_requests: { id: string; student_name: string; seat_name: string; seat_type: string; move_cost: number; status: string }[];
  seat_catalog: { id: string; code: string; name: string; type: string; rent: number; move_cost: number; active: boolean; student_name?: string }[];
  job_submissions: TeacherJobSubmission[];
};

const nav: { id: StudentView; label: string; icon: string; feature?: string; bankerOnly?: boolean }[] = [
  { id: "home", label: "오늘의 생활", icon: "⌂" }, { id: "jobs", label: "일자리 탐험", icon: "✦", feature: "job_board" },
  { id: "wallet", label: "나의 경제", icon: "₩", feature: "wallet" }, { id: "bank", label: "은행 업무", icon: "▥", feature: "bank", bankerOnly: true },
  { id: "growth", label: "진로 성장", icon: "◎", feature: "competencies" },
  { id: "room", label: "마이룸", icon: "▣", feature: "my_room" },
];
function studentNav(student: StudentData) { return nav.filter((item) => !item.bankerOnly || student.basic_job === "은행원"); }
const competencyNames: Record<string, string> = {
  self_management: "자기관리 역량", knowledge_information: "지식정보처리 역량", creative_thinking: "창의적 사고 역량",
  aesthetic_emotion: "심미적 감성 역량", collaborative_communication: "협력적 소통 역량", community: "공동체 역량",
};
const transactionNames: Record<string, string> = { salary: "기본직업 월급", job_reward: "공고 보수", rent: "주거비", saving: "저축", withdrawal: "출금", donation: "공동체기금 기부", seat_move: "자리 이동", adjustment: "잔액 조정" };
const stageNames = ["첫걸음", "생활 시작", "직업 탐험", "성장 발견", "나의 세계", "함께하는 사회"];

function Avatar({ small = false, job = "", custom, badge }: { small?: boolean; job?: string | null; custom?: StudentData["avatar"]; badge?: Badge }) {
  const prop = job?.includes("사서") ? "📚" : job?.includes("기자") ? "✎" : job?.includes("제작") || job?.includes("엔지니어") ? "⚒" : job?.includes("디자이너") ? "✦" : "₩";
  return <div className={`${small ? "avatar avatar--small" : "avatar"} avatar-bg-${custom?.background ?? "violet"} hair-${custom?.hair ?? "short"}`} aria-label={`${job || "학생"} 캐릭터`}><span className="avatar__sparkle sparkle-left">✦</span><span className="avatar__sparkle sparkle-right">♡</span><span className="avatar__ear avatar__ear--left" /><span className="avatar__ear avatar__ear--right" /><span className="avatar__hair" /><span className="avatar__face"><i className="avatar__cheek avatar__cheek--left" /><i className="avatar__cheek avatar__cheek--right" /></span><span className="avatar__body" /><span className="avatar__collar">♡</span><span className="avatar__shoe avatar__shoe--left" /><span className="avatar__shoe avatar__shoe--right" /><span className="avatar__case">{prop}</span>{badge ? <span className="avatar__badge" title={badge.name}>{badge.icon}</span> : null}</div>;
}

function Brand() { return <div className="brand"><span className="brand__mark">F</span><span><strong>미래탐험대</strong><small>우리 반 진로생활</small></span></div>; }

function Login({ onStudent, onTeacher }: { onStudent: (student: StudentData) => void; onTeacher: (teacher: TeacherData) => void }) {
  const [role, setRole] = useState<"student" | "teacher">("student");
  const [classCode, setClassCode] = useState(""); const [displayName, setDisplayName] = useState(""); const [pin, setPin] = useState("");
  const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  const submit = async (event: FormEvent) => {
    event.preventDefault(); if (!/^\d{4}$/.test(pin)) { setError("PIN은 숫자 4자리로 입력해 주세요."); return; }
    setLoading(true); setError("");
    try {
      const response = await fetch(`/api/${role}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "login", classCode, displayName, pin }) });
      const result = await response.json();
      if (!response.ok || !result.ok) { setError(result.message ?? "로그인 정보를 다시 확인해 주세요."); return; }
      if (role === "student") onStudent(result.student as StudentData); else { const refreshed = await fetch("/api/teacher", { cache: "no-store" }); const session = await refreshed.json(); onTeacher((session.teacher ?? result.teacher) as TeacherData); }
    } catch { setError("지금은 접속할 수 없어요. 잠시 후 다시 시도해 주세요."); } finally { setLoading(false); }
  };
  return <main className="voyage-login"><div className="voyage-sky"><span className="cloud cloud-a" /><span className="cloud cloud-b" /><span className="sun-glow" /></div><div className="voyage-copy"><div className="voyage-brand"><span>F</span> FUTURE ODYSSEY</div><p>교실에서 시작하는 나의 미래 항해</p><h1>다양한 일을 경험하며<br /><em>나의 가능성</em>을 발견해요.</h1></div><div className="sea-layer sea-back" /><div className="sea-layer sea-front" /><div className="little-boat" aria-hidden="true"><span className="boat-sail" /><span className="boat-mast" /><span className="boat-hull" /></div><section className="login-card" aria-label="로그인"><span className="login-compass">✦</span><small>WELCOME ABOARD</small><h2>{role === "student" ? "나의 미래 항해 시작" : "학급 운영 시작"}</h2><div className="login-role-tabs" role="tablist"><button type="button" className={role === "student" ? "active" : ""} onClick={() => { setRole("student"); setError(""); }}>학생</button><button type="button" className={role === "teacher" ? "active" : ""} onClick={() => { setRole("teacher"); setError(""); }}>교사</button></div><form onSubmit={submit}><label>학급코드<input value={classCode} onChange={(e) => setClassCode(e.target.value.slice(0, 12))} placeholder="학급코드" /></label><label>{role === "student" ? "이름" : "교사 이름"}<input value={displayName} onChange={(e) => setDisplayName(e.target.value.slice(0, 30))} placeholder="이름을 입력하세요" /></label><label>숫자 4자리 PIN<input type="password" inputMode="numeric" maxLength={4} value={pin} onChange={(e) => setPin(e.target.value.replace(/\D/g, "").slice(0, 4))} placeholder="● ● ● ●" /></label>{error ? <div className="login-error" role="alert">! {error}</div> : null}<button className="voyage-button" disabled={loading}>{loading ? "확인하고 있어요…" : "항해 시작"}<span>→</span></button></form><div className="login-help">계정 정보는 담임 선생님에게 확인하세요.</div></section></main>;
}

function PinSetup({ student, onComplete }: { student: StudentData; onComplete: (student: StudentData) => void }) {
  const [pin, setPin] = useState(""); const [confirm, setConfirm] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); if (!/^\d{4}$/.test(pin) || pin !== confirm) { setError("같은 숫자 4자리를 두 번 입력해 주세요."); return; } setLoading(true); const response = await fetch("/api/student", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "change-pin", pin }) }); const result = await response.json(); setLoading(false); if (!result.ok) { setError(result.message ?? "PIN을 바꾸지 못했어요."); return; } onComplete(result.student as StudentData); };
  return <main className="pin-page"><section className="pin-card"><span className="pin-lock">⌾</span><small>첫 항해 준비</small><h1>{student.display_name}님만의 PIN을<br />만들어 주세요.</h1><p>친구에게 알려주지 않는 숫자 4자리예요.</p><form onSubmit={submit}><label>새 PIN<input type="password" inputMode="numeric" maxLength={4} value={pin} onChange={(e) => setPin(e.target.value.replace(/\D/g, ""))} /></label><label>PIN 확인<input type="password" inputMode="numeric" maxLength={4} value={confirm} onChange={(e) => setConfirm(e.target.value.replace(/\D/g, ""))} /></label>{error ? <div className="login-error">{error}</div> : null}<button className="voyage-button" disabled={loading}>{loading ? "저장 중…" : "내 PIN으로 설정"}</button></form></section></main>;
}

function Sidebar({ student, active, onChange, onLogout }: { student: StudentData; active: StudentView; onChange: (view: StudentView) => void; onLogout: () => void }) {
  return <aside className="sidebar"><Brand /><nav className="side-nav" aria-label="학생 메뉴">{studentNav(student).map((item) => { const locked = Boolean(item.feature && !student.feature_unlocks.includes(item.feature)); return <button key={item.id} className={`${active === item.id ? "active" : ""} ${locked ? "nav-locked" : ""}`} onClick={() => onChange(item.id)}><span>{locked ? "◌" : item.icon}</span><span className="nav-copy">{item.label}{item.id === "bank" && student.bank_queue.length ? <b className="nav-count">{student.bank_queue.length}</b> : null}{locked ? <small>{item.id === "jobs" ? "기본업무 2회 후 열려요" : "경험을 쌓으면 열려요"}</small> : null}</span></button>; })}</nav><div className="side-tip"><span>💡</span><strong>이번 주 생각</strong><p>시간이 빨리 간 일은 무엇이었나요?</p></div><div className="side-profile"><Avatar small job={student.basic_job} /><span><strong>{student.display_name}</strong><small>{student.basic_job ?? "직업 대기"} · {stageNames[Math.max(0, student.growth_stage - 1)]}</small></span><button onClick={onLogout} aria-label="로그아웃">↪</button></div></aside>;
}

function Topbar({ label, onLogout }: { label: string; onLogout?: () => void }) { return <header className="topbar"><div className="mobile-brand"><Brand /></div><div className="week-pill"><span /> {label}</div><div className="top-actions">{onLogout ? <button className="role-switch" onClick={onLogout}>로그아웃</button> : null}</div></header>; }

const proofInfo: Record<BasicJobTask["proof_mode"], { icon: string; label: string; help: string }> = {
  system: { icon: "⚙", label: "자동 기록", help: "앱 안에서 처리하면 자동으로 남아요." },
  photo: { icon: "▣", label: "사진", help: "활동 또는 결과가 보이는 사진을 남겨요." },
  result: { icon: "↗", label: "결과물", help: "사진이나 결과물 링크를 남겨요." },
  peer: { icon: "♡", label: "친구 확인", help: "함께한 친구가 활동을 확인해요." },
  checklist: { icon: "✓", label: "체크 기록", help: "확인한 항목과 결과를 한 문장으로 남겨요." },
};

function BasicJobWorkPanel({ student, busy, act }: { student: StudentData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const tasks = student.basic_job_task_catalog ?? [];
  const submissions = student.basic_job_submissions ?? [];
  const peerQueue = student.peer_review_queue ?? [];
  const classmates = student.classmates ?? [];
  const [selectedId, setSelectedId] = useState("");
  const [summary, setSummary] = useState("");
  const [evidenceUrl, setEvidenceUrl] = useState("");
  const [photoName, setPhotoName] = useState("");
  const [verifierId, setVerifierId] = useState("");
  const [checked, setChecked] = useState(false);
  const selected = tasks.find((task) => task.id === selectedId);

  const choose = (task: BasicJobTask) => {
    setSelectedId(task.id); setSummary(""); setEvidenceUrl(""); setPhotoName(""); setVerifierId(""); setChecked(false);
    window.setTimeout(() => document.getElementById("basic-job-form")?.scrollIntoView({ behavior: "smooth", block: "center" }), 20);
  };
  const addPhoto = (file?: File) => {
    if (!file) return;
    if (file.size > 750_000) { window.alert("사진은 750KB보다 작게 줄여 주세요."); return; }
    const reader = new FileReader();
    reader.onload = () => { setEvidenceUrl(String(reader.result ?? "")); setPhotoName(file.name); };
    reader.readAsDataURL(file);
  };
  const submit = async () => {
    if (!selected) return;
    await act("submit-basic-task", { taskId: selected.id, summary, evidenceUrl, verifierStudentId: verifierId || null });
    setSelectedId(""); setSummary(""); setEvidenceUrl(""); setPhotoName(""); setVerifierId(""); setChecked(false);
  };
  const needsEvidence = selected?.proof_mode === "photo" || selected?.proof_mode === "result";
  const ready = Boolean(selected && summary.trim().length >= 5 && (!needsEvidence || evidenceUrl) && (selected.proof_mode !== "peer" || verifierId) && (selected.proof_mode !== "checklist" || checked));

  return <section className="basic-work" id="basic-job-work"><div className="section-head"><div><span className="eyebrow">나의 기본직업</span><h2>한 일을 증거와 함께 남겨요</h2><p>직업에 맞는 방식으로 기록하면 기본직업 경험에 반영됩니다.</p></div><span className="basic-work-count">이번 학기 {student.basic_job_tasks_completed}회</span></div><div className="basic-task-grid">{tasks.map((task) => { const proof = proofInfo[task.proof_mode]; const latest = submissions.find((item) => item.task_id === task.id); return <article key={task.id} className={`basic-task-card ${selectedId === task.id ? "active" : ""}`}><div className="basic-task-head"><span>{proof.icon}</span><b>{proof.label}</b></div><h3>{task.title}</h3><p>{task.description}</p><small>{proof.help}</small>{latest ? <span className={`proof-status ${latest.status}`}>{latest.status === "confirmed" ? "기록 완료" : latest.status === "pending_confirmation" ? "친구 확인 중" : "다시 기록하기"}</span> : null}<button disabled={busy || task.proof_mode === "system"} onClick={() => choose(task)}>{task.proof_mode === "system" ? "업무 처리 시 자동 기록" : "활동 기록하기"}</button></article>; })}</div>{selected ? <article className="panel basic-proof-form" id="basic-job-form"><div className="panel-title"><div><span className="eyebrow">{proofInfo[selected.proof_mode].label}</span><h2>{selected.title}</h2></div><button type="button" onClick={() => setSelectedId("")} aria-label="기록 닫기">×</button></div><label>무엇을 했나요?<textarea value={summary} onChange={(e) => setSummary(e.target.value)} placeholder="내가 실제로 한 일을 한 문장으로 적어요." /></label>{needsEvidence ? <><label className="photo-field">사진 선택<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => addPhoto(e.target.files?.[0])} /><span>{photoName || "사진 선택 (750KB 이하)"}</span></label><input aria-label="결과물 링크" value={evidenceUrl.startsWith("data:") ? "" : evidenceUrl} onChange={(e) => { setEvidenceUrl(e.target.value); setPhotoName(""); }} placeholder="또는 결과물 링크를 붙여 넣어요" /></> : null}{selected.proof_mode === "peer" ? <label>확인해 줄 친구<select value={verifierId} onChange={(e) => setVerifierId(e.target.value)}><option value="">친구 선택</option>{classmates.map((mate) => <option key={mate.id} value={mate.id}>{mate.name} · {mate.job ?? "친구"}</option>)}</select></label> : null}{selected.proof_mode === "checklist" ? <label className="check-proof"><input type="checkbox" checked={checked} onChange={(e) => setChecked(e.target.checked)} />점검 항목을 실제로 확인했고 결과를 기록했어요.</label> : null}<button className="apply-button" disabled={busy || !ready} onClick={submit}>{busy ? "기록 중…" : selected.proof_mode === "peer" ? "친구에게 확인 요청" : "증거와 함께 기록"}</button></article> : null}{peerQueue.length ? <article className="panel peer-proof-panel"><div className="panel-title"><div><span className="eyebrow">친구 확인 요청</span><h2>내가 함께한 일이 맞나요?</h2></div><span className="count-badge">{peerQueue.length}</span></div>{peerQueue.map((item) => <div className="peer-proof-row" key={item.id}><p><strong>{item.student_name} · {item.task_title}</strong><small>{item.summary}</small></p><button disabled={busy} onClick={() => act("review-basic-task", { submissionId: item.id, decision: "confirm" })}>맞아요</button><button className="subtle" disabled={busy} onClick={() => act("review-basic-task", { submissionId: item.id, decision: "reject" })}>보완 요청</button></div>)}</article> : null}{submissions.length ? <div className="basic-history"><strong>최근 기본업무 기록</strong>{submissions.slice(0, 4).map((item) => <span key={item.id}>{item.title}<b className={item.status}>{item.status === "confirmed" ? "완료" : item.status === "pending_confirmation" ? `${item.verifier_name ?? "친구"} 확인 중` : "보완 필요"}</b></span>)}</div> : null}</section>;
}

function HomeView({ student, busy, act, openJobs }: { student: StudentData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void>; openJobs: () => void }) {
  const goal = student.community_goal ?? {};
  const jobBoardUnlocked = student.feature_unlocks.includes("job_board");
  return <><section className="welcome-row"><div><span className="eyebrow">오늘의 진로생활</span><h1>{student.display_name}님, 오늘은 어떤 일을<br /><em>경험해 볼까요?</em></h1><p>친구와 함께 실제 교실의 일을 해보며 나의 강점을 발견해요.</p></div></section><section className="profile-hero"><div className="profile-art"><Avatar job={student.basic_job} /></div><div className="profile-copy"><span className="job-chip">나의 기본직업</span><h2>{student.basic_job ?? "직업 배정 대기"}</h2><p>{student.job_world ?? "교실에서 맡은 역할을 하나씩 경험해요."}</p><div className="role-tasks"><span>기본업무 {student.basic_job_tasks_completed}회</span><span>공고 완료 {student.jobs_completed}회</span></div></div><div className="week-mission"><span>기본직업 기록</span><strong>한 일을 어떻게 증명할까요?</strong><small>직업에 맞게 사진·결과물·친구 확인으로 남겨요.</small><button className="apply-button" onClick={() => document.getElementById("basic-job-work")?.scrollIntoView({ behavior: "smooth" })}>나의 기본업무 보기</button></div></section><section className="money-grid"><article className="money-card"><span className="round-icon purple">₩</span><div><p>사용 가능한 현금</p><strong>{student.cash.toLocaleString()}꿈</strong><small>거래는 모두 안전하게 기록돼요.</small></div></article><article className="money-card"><span className="round-icon green">▥</span><div><p>차곡차곡 저축</p><strong>{student.savings.toLocaleString()}꿈</strong><small>3,000꿈부터 마이룸이 열려요.</small></div></article><article className="money-card"><span className="round-icon orange">⌂</span><div><p>현재 자리</p><strong>{student.housing_name ?? "배정 대기"}</strong><small>자리마다 특징과 주거비가 달라요.</small></div></article></section><BasicJobWorkPanel student={student} busy={busy} act={act} />{jobBoardUnlocked ? student.postings.length ? <><section className="section-head"><div><span className="eyebrow">이번 주 일자리</span><h2>궁금한 일을 골라보세요</h2><p>홈에서는 요약만 보고, 지원과 활동 기록은 일자리 탐험에서 이어가요.</p></div><button onClick={openJobs}>전체 공고·내 활동 보기 →</button></section><div className="job-grid home-jobs">{student.postings.slice(0, 3).map((posting) => <CompactPosting key={posting.id} posting={posting} application={student.applications.find((a) => a.posting_id === posting.id)} busy={busy} act={act} openJobs={openJobs} />)}</div></> : <article className="panel empty-state"><strong>이번 주 공고를 준비하고 있어요.</strong><p>선생님이 이번 주를 시작하면 새로운 일이 열립니다.</p></article> : null}{goal.id ? <Community goal={goal} cash={student.cash} busy={busy} act={act} /> : null}</>;
}

function skillsText(rewards: Record<string, number>) { return Object.entries(rewards).map(([key, value]) => `${competencyNames[key] ?? key} +${value}`); }

function CompactPosting({ posting, application, busy, act, openJobs }: { posting: Posting; application?: Application; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void>; openJobs: () => void }) {
  const buttonLabel = !application ? "이 일 경험하기" : application.status === "waitlisted" ? "대기 중" : application.status === "completed" ? "완료 기록 보기" : "활동 기록·완료하기";
  const openDetail = Boolean(application && application.status !== "waitlisted");
  return <article className="job-card"><div className="job-card__head"><span className="job-icon violet">✦</span><span className="world-label">{posting.world}</span></div><h3>{posting.title}</h3><p>{posting.description}</p><div className="job-meta"><span>{posting.assigned_count}/{posting.capacity}명</span><span>{posting.duration_minutes}분</span><strong>+{posting.reward}꿈</strong></div><div className="skill-tags">{skillsText(posting.competency_rewards).map((skill) => <span key={skill}>{skill}</span>)}</div><button className={`apply-button ${application ? "applied" : ""}`} disabled={busy || application?.status === "waitlisted"} onClick={() => openDetail ? openJobs() : act("apply-job", { postingId: posting.id })}>{buttonLabel}</button></article>;
}

function JobsView({ student, busy, act }: { student: StudentData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const [filter, setFilter] = useState("전체"); const worlds = ["전체", ...Array.from(new Set(student.postings.map((p) => p.world)))];
  const [draft, setDraft] = useState<Record<string, { summary: string; resultUrl: string; photoName: string; fun: number; difficulty: number }>>({});
  const visible = filter === "전체" ? student.postings : student.postings.filter((p) => p.world === filter);
  const update = (id: string, value: Partial<{ summary: string; resultUrl: string; photoName: string; fun: number; difficulty: number }>) => setDraft((current) => {
    const existing = current[id] ?? { summary: "", resultUrl: "", photoName: "", fun: 3, difficulty: 3 };
    return { ...current, [id]: { ...existing, ...value } };
  });
  const addPhoto = (id: string, file?: File) => {
    if (!file) return;
    if (file.size > 750_000) { window.alert("사진은 750KB보다 작게 줄여 주세요."); return; }
    const reader = new FileReader();
    reader.onload = () => update(id, { resultUrl: String(reader.result ?? ""), photoName: file.name });
    reader.readAsDataURL(file);
  };
  return <><section className="page-heading"><span className="eyebrow">일자리 탐험</span><h1>어떤 일을 해볼까요?</h1><p>기본직업과 달라도 괜찮아요. 지원부터 활동 증거 제출까지 이곳에서 이어집니다.</p></section><div className="filter-row">{worlds.map((world) => <button key={world} className={filter === world ? "active" : ""} onClick={() => setFilter(world)}>{world}</button>)}</div><div className="jobs-summary"><strong>열린 공고 {student.postings.length}개</strong><span>나의 지원 {student.applications.length}개</span><span>완료 {student.jobs_completed}개</span></div><div className="job-grid all-jobs">{visible.map((posting) => { const application = student.applications.find((a) => a.posting_id === posting.id); const needsRevision = application?.status === "completed" && application.evidence_review_status === "revision_requested"; const form = draft[application?.id ?? ""] ?? { summary: needsRevision ? application?.summary ?? "" : "", resultUrl: needsRevision ? application?.result_url ?? "" : "", photoName: "", fun: needsRevision ? application?.fun_rating ?? 3 : 3, difficulty: needsRevision ? application?.difficulty_rating ?? 3 : 3 }; return <article className="job-card job-card-live" key={posting.id}><div className="job-card__head"><span className="job-icon violet">✦</span><span className="world-label">{posting.world}</span></div><h3>{posting.title}</h3><p>{posting.description}</p><div className="job-meta"><span>{posting.assigned_count}/{posting.capacity}명</span><span>{posting.duration_minutes}분</span><strong>+{posting.reward}꿈</strong></div><div className="skill-tags">{skillsText(posting.competency_rewards).map((skill) => <span key={skill}>{skill}</span>)}</div>{!application ? <button className="apply-button" disabled={busy} onClick={() => act("apply-job", { postingId: posting.id })}>지원하기</button> : application.status === "completed" && !needsRevision ? <div className="completion-done">✓ 완료 기록과 보상이 반영됐어요.{application.evidence_review_status === "reviewed" ? <small>선생님도 증거를 확인했어요.</small> : null}</div> : application.status === "waitlisted" ? <div className="completion-wait">현재 대기 중이에요.</div> : <div className="completion-form">{needsRevision ? <div className="revision-notice"><strong>보완 요청이 왔어요.</strong><span>{application.evidence_feedback}</span></div> : null}<label>무엇을 했나요?<textarea value={form.summary} onChange={(e) => update(application.id, { summary: e.target.value })} placeholder="내가 맡아 실제로 한 일을 적어요." /></label><label className="photo-field">결과물 사진 또는 링크<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => addPhoto(application.id, e.target.files?.[0])} /><span>{form.photoName || (needsRevision && form.resultUrl ? "기존 증거 유지 또는 새 사진 선택" : "사진 선택 (750KB 이하)")}</span></label><input aria-label="결과물 링크" value={form.resultUrl.startsWith("data:") ? "" : form.resultUrl} onChange={(e) => update(application.id, { resultUrl: e.target.value, photoName: "" })} placeholder="또는 결과물 링크를 붙여 넣어요" /><div className="rating-row"><label>재미 <select value={form.fun} onChange={(e) => update(application.id, { fun: Number(e.target.value) })}>{[1,2,3,4,5].map((n) => <option key={n}>{n}</option>)}</select></label><label>어려움 <select value={form.difficulty} onChange={(e) => update(application.id, { difficulty: Number(e.target.value) })}>{[1,2,3,4,5].map((n) => <option key={n}>{n}</option>)}</select></label></div><button className="apply-button" disabled={busy || form.summary.trim().length < 5} onClick={() => act(needsRevision ? "resubmit-job-evidence" : "complete-job", { applicationId: application.id, summary: form.summary, resultUrl: form.resultUrl, fun: form.fun, difficulty: form.difficulty })}>{needsRevision ? "보완해서 다시 제출" : "완료 제출"}</button></div>}</article>; })}</div></>;
}

function Community({ goal, cash, busy, act }: { goal: CommunityGoal; cash: number; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const current = goal.current_amount ?? 0; const target = goal.target_amount ?? 1; const percent = Math.min(100, Math.round(current / target * 100));
  const [amount, setAmount] = useState(100);
  return <article className="panel community-card"><div className="community-visual"><span>우리 반</span><strong>{goal.title}</strong><div className="ball">●</div></div><div className="community-copy"><span className="eyebrow">함께 만드는 공동체 목표</span><h2>{goal.title}</h2><p>{goal.description}</p><div className="fund-row"><span>현재 기금</span><strong>{current.toLocaleString()} <small>/ {target.toLocaleString()}꿈</small></strong></div><div className="progress"><i style={{ width: `${percent}%` }} /></div><div className="fund-row participation"><span>{goal.min_donations}회 이상 참여한 친구</span><strong>{goal.qualified_students ?? 0} / {goal.total_students ?? 0}명</strong></div><div className="donation-actions"><select aria-label="기부 금액" value={amount} onChange={(e) => setAmount(Number(e.target.value))}>{[100,300,500].map((value) => <option key={value} value={value}>{value}꿈</option>)}</select><button className="donate-button" disabled={busy || cash < amount || goal.status === "achieved"} onClick={() => act("donate", { goalId: goal.id, amount })}>{goal.status === "achieved" ? "목표 달성 ✓" : "함께 보태기"}</button></div></div></article>;
}

function WalletView({ student, busy, act }: { student: StudentData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const [amount, setAmount] = useState(100); const [type, setType] = useState("saving");
  return <><section className="page-heading"><span className="eyebrow">나의 경제</span><h1>돈의 흐름을 직접 경험해요</h1><p>잔액은 학생이 직접 바꾸지 않고, 은행 확인과 안전한 기록을 거쳐 움직입니다.</p></section><div className="wallet-balance"><div><span>현금</span><strong>{student.cash.toLocaleString()} <small>꿈</small></strong><p>지금 사용할 수 있는 돈</p></div><div><span>저축</span><strong>{student.savings.toLocaleString()} <small>꿈</small></strong><p>유지할수록 마이룸 아이템 해금</p></div><div className="wallet-actions bank-request-form"><select value={type} onChange={(e) => setType(e.target.value)} aria-label="은행 신청 종류"><option value="saving">저축 신청</option><option value="withdrawal">출금 신청</option></select><select value={amount} onChange={(e) => setAmount(Number(e.target.value))} aria-label="신청 금액">{[100,200,300,500,1000].map((value) => <option key={value} value={value}>{value}꿈</option>)}</select><button disabled={busy} onClick={() => act("bank-request", { type, amount })}>은행에 신청</button></div></div><div className="dashboard-grid wallet-grid"><article className="panel"><div className="panel-title"><div><span className="eyebrow">거래 기록</span><h2>최근 돈의 흐름</h2></div></div><div className="transaction-list">{student.transactions.length ? student.transactions.map((tx) => { const delta = tx.cash_delta || tx.savings_delta; return <div key={tx.id}><span className={`timeline-icon ${delta >= 0 ? "green" : "orange"}`}>{delta >= 0 ? "↙" : "↗"}</span><p><strong>{transactionNames[tx.transaction_type] ?? tx.transaction_type}</strong><small>{new Date(tx.created_at).toLocaleDateString("ko-KR")} · 현금 {tx.cash_after.toLocaleString()}꿈 · 저축 {tx.savings_after.toLocaleString()}꿈</small></p><b className={delta >= 0 ? "plus" : ""}>{delta > 0 ? "+" : ""}{delta.toLocaleString()}꿈</b></div>; }) : <p className="empty-copy">아직 거래 기록이 없어요.</p>}</div></article><article className="panel"><div className="panel-title"><div><span className="eyebrow">은행 신청</span><h2>처리 상태</h2></div></div><div className="request-list">{student.bank_requests.length ? student.bank_requests.map((request) => <div key={request.id}><strong>{request.request_type === "saving" ? "저축" : "출금"} {request.amount.toLocaleString()}꿈</strong><span className={`status-pill ${request.status}`}>{request.status === "pending" ? "확인 대기" : request.status === "approved" ? "승인" : "반려"}</span></div>) : <p className="empty-copy">신청 내역이 없어요.</p>}</div></article></div><article className="panel seat-panel"><div className="panel-title"><div><span className="eyebrow">자리 이동</span><h2>나에게 맞는 공간 찾기</h2></div></div><div className="seat-grid">{student.seats.map((seat) => <button key={seat.id} disabled={!seat.available || busy || seat.name === student.housing_name} onClick={() => act("request-seat", { seatId: seat.id })}><strong>{seat.name}</strong><span>{seat.type} · 주거비 {seat.rent}꿈</span><small>{seat.available ? `이동비 ${seat.move_cost}꿈` : "사용 중"}</small></button>)}</div></article>{student.community_goal?.id ? <Community goal={student.community_goal} cash={student.cash} busy={busy} act={act} /> : null}</>;
}

function BankView({ student, busy, act }: { student: StudentData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const ownPending = student.bank_requests.filter((request) => request.status === "pending").length;
  return <><section className="page-heading bank-heading"><div><span className="eyebrow">은행원 전용</span><h1>친구들의 은행 신청을 확인해요</h1><p>승인하면 시스템이 잔액과 거래 기록을 안전하게 처리합니다.</p></div><div className="bank-pending-count"><span>처리 대기</span><strong>{student.bank_queue.length}건</strong></div></section><article className="panel bank-safety"><span>!</span><p><strong>잔액은 직접 수정할 수 없어요.</strong><small>신청 내용을 확인한 뒤 승인 또는 반려만 선택해요. 내가 보낸 신청은 다른 은행원이나 선생님이 처리합니다.</small></p></article><article className="panel bank-queue bank-work-panel"><div className="panel-title"><div><span className="eyebrow">오늘의 은행 업무</span><h2>저축·출금 신청 확인</h2></div><span className="count-badge">{student.bank_queue.length}</span></div>{student.bank_queue.length ? student.bank_queue.map((request) => <div className="review-row" key={request.id}><p><strong>{request.student_name}</strong><small>{request.request_type === "saving" ? "저축" : "출금"} · {request.amount.toLocaleString()}꿈</small></p><button disabled={busy} onClick={() => act("review-bank", { requestId: request.id, decision: "approve" })}>승인</button><button className="subtle" disabled={busy} onClick={() => act("review-bank", { requestId: request.id, decision: "reject" })}>반려</button></div>) : <div className="bank-empty"><span>✓</span><strong>지금은 확인할 신청이 없어요.</strong><p>{ownPending ? `내가 보낸 신청 ${ownPending}건은 직접 승인할 수 없어 선생님 확인을 기다리고 있어요.` : "친구가 저축이나 출금을 신청하면 이곳에 바로 나타나요."}</p></div>}</article></>;
}

function GrowthView({ student, busy, act }: { student: StudentData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const max = Math.max(10, ...student.competencies.map((item) => item.xp));
  const completed = student.applications.filter((app) => app.status === "completed");
  const [hair, setHair] = useState(student.avatar?.hair ?? "short"); const [background, setBackground] = useState(student.avatar?.background ?? "violet"); const [badgeKey, setBadgeKey] = useState(student.avatar?.displayed_badge_key ?? "");
  const points = student.competencies.map((item, index) => { const angle = (-90 + index * 60) * Math.PI / 180; const radius = 12 + 36 * item.xp / max; return `${50 + Math.cos(angle) * radius}% ${50 + Math.sin(angle) * radius}%`; }).join(",");
  const displayed = student.badges.find((badge) => badge.key === badgeKey);
  return <><section className="page-heading"><span className="eyebrow">진로 성장</span><h1>직업 이름보다, 내가 해본 일을 모아요</h1><p>점수는 순위가 아니라 어떤 힘을 자주 사용했는지 보여주는 나만의 기록입니다.</p></section><div className="growth-layout"><article className="panel growth-card"><div className="panel-title competency-heading"><div><span className="eyebrow">2022 개정 교육과정</span><h2>나의 여섯 가지 핵심역량</h2></div><span>비교·순위 없음</span></div><div className="growth-body"><div className="radar-wrap"><span className="radar-grid grid-one" /><span className="radar-grid grid-two" /><span className="radar-grid grid-three" /><span className="radar-shape" style={{ clipPath: `polygon(${points})` }} />{student.competencies.map((item, index) => <span key={item.key} className={`radar-label ${["top","tr","br","bottom","bl","tl"][index]}`}>{item.name.replace(" 역량","")}</span>)}</div><div className="live-skill-list">{student.competencies.map((item) => <details className="live-skill" key={item.key}><summary><strong>{item.name}</strong><span>{item.xp} 경험점</span></summary><div className="progress"><i style={{ width: `${Math.round(item.xp / max * 100)}%`, background: item.color }} /></div><p>{item.description}</p></details>)}</div></div></article><article className="panel experience-card"><span className="eyebrow">직업 경험 기록</span><h2>이번 학기 {completed.length}번의 경험</h2><div className="career-chips">{student.career_experiences?.map((item) => <span key={`${item.kind}-${item.job}`}><strong>{item.job}</strong>{item.count}회</span>)}</div><div className="experience-list">{completed.length ? completed.map((app) => <div key={app.id}><span>✓</span><p><strong>{app.title}</strong><small>{app.world ? `${app.world} · ` : ""}재미 {app.fun_rating}/5 · 어려움 {app.difficulty_rating}/5</small></p></div>) : <p className="empty-copy">첫 공고를 완료하면 이곳에 경험이 쌓여요.</p>}</div></article></div><div className="growth-layout"><article className="panel"><div className="panel-title"><div><span className="eyebrow">나의 배지</span><h2>경험으로 얻은 표시</h2></div></div><div className="badge-collection">{student.badges.length ? student.badges.map((badge) => <div key={badge.key}><span>{badge.icon}</span><strong>{badge.name}</strong><small>{badge.description}</small></div>) : <p className="empty-copy">첫 경험 배지를 만나러 가볼까요?</p>}</div></article><article className="panel avatar-editor"><div><span className="eyebrow">나의 모습</span><h2>캐릭터 꾸미기</h2><Avatar job={student.basic_job} custom={{ hair, background, displayed_badge_key: badgeKey || null }} badge={displayed} /></div><div className="avatar-options"><label>머리 모양<select value={hair} onChange={(e) => setHair(e.target.value)}><option value="short">단정한 머리</option><option value="wave">웨이브</option><option value="bob">단발</option><option value="spiky">활동적인 머리</option></select></label><label>배경<select value={background} onChange={(e) => setBackground(e.target.value)}><option value="violet">보랏빛 탐험</option><option value="forest">초록 숲</option><option value="sunset">노을</option><option value="sky">맑은 하늘</option><option value="maker">메이커실</option></select></label><label>대표 배지<select value={badgeKey} onChange={(e) => setBadgeKey(e.target.value)}><option value="">표시 안 함</option>{student.badges.map((badge) => <option key={badge.key} value={badge.key}>{badge.icon} {badge.name}</option>)}</select></label><button disabled={busy} onClick={() => act("update-avatar", { hair, background, badgeKey: badgeKey || null })}>내 모습 저장</button></div></article></div></>;
}

function RoomView({ student, busy, act }: { student: StudentData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const equipped = student.room_items.filter((item) => item.equipped); const next = student.room_items.filter((item) => !item.unlocked).sort((a,b) => a.required-b.required)[0];
  const has = (key: string) => equipped.some((item) => item.key === key);
  const displayed = student.badges.find((badge) => badge.key === student.avatar?.displayed_badge_key);
  return <><section className="page-heading room-heading"><div><span className="eyebrow">나의 공간</span><h1>저축을 지키며 취향을 표현해요</h1><p>물건을 사는 대신 저축 목표에 도달하면 아이템이 열립니다.</p></div><div className="room-level"><span>다음 해금</span><strong>{next ? `${next.name} · ${Math.max(0,next.required-student.savings).toLocaleString()}꿈 남음` : "모두 해금"}</strong></div></section><div className="room-layout"><div className={`room-scene cute-room ${has("wall_nature") ? "cute-room--nature" : ""}`}><div className="room-sunbeam" /><div className="room-cloud cloud-one">☁</div><div className="room-cloud cloud-two">☁</div>{has("rug") ? <div className="cute-rug"><i /><i /><i /></div> : null}{has("bookshelf") ? <div className="cute-bookshelf"><span>📕</span><span>📗</span><span>📘</span><b>☁</b></div> : null}{has("maker_shelf") ? <div className="maker-box"><span>🔧</span><span>✂️</span><strong>MAKE!</strong></div> : null}{has("plant") ? <div className="cute-plant"><i /><i /><i /><b>⌣</b></div> : null}<div className={`cute-desk ${has("digital_desk") ? "cute-desk--digital" : ""}`}><span>{has("digital_desk") ? "⌨" : "✎"}</span><i>{has("digital_desk") ? "▰" : "♡"}</i></div>{has("chair_reading") ? <div className="reading-chair"><span>☆</span></div> : <div className="basic-stool" />}<div className="room-avatar"><Avatar job={student.basic_job} custom={student.avatar} badge={displayed} /></div><div className="room-label"><span>♡</span>{equipped.length ? equipped.map((item) => item.visual).join(" ") : "나의 포근한 마이룸"}</div></div><aside className="panel room-controls live-room-controls"><span className="eyebrow">슬롯형 꾸미기</span><h2>귀여운 방 소품</h2>{student.room_items.map((item) => <button key={item.key} disabled={!item.unlocked || busy} className={item.equipped ? "active" : ""} onClick={() => act("equip-room", { itemKey: item.key })}><i>{item.visual}</i><span><strong>{item.name}</strong><small>{item.unlocked ? `${item.slot} · ${item.style}` : `저축 ${item.required.toLocaleString()}꿈에 해금`}</small></span>{item.equipped ? <b>✓</b> : null}</button>)}</aside></div></>;
}

function TeacherSetupPanels({ teacher, busy, act }: { teacher: TeacherData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const [name, setName] = useState(""); const [number, setNumber] = useState(1); const [jobCode, setJobCode] = useState(teacher.job_catalog?.[0]?.code ?? ""); const [tempPin, setTempPin] = useState("");
  return <div className="teacher-grid teacher-setup"><article className="panel"><div className="panel-title"><div><span className="eyebrow">학생 계정</span><h2>학생 등록</h2></div></div><div className="teacher-form"><input value={name} onChange={(e) => setName(e.target.value)} placeholder="학생 이름" /><input type="number" min={1} value={number} onChange={(e) => setNumber(Number(e.target.value))} aria-label="학생 번호" /><select value={jobCode} onChange={(e) => setJobCode(e.target.value)} aria-label="기본직업">{(teacher.job_catalog ?? []).map((job) => <option key={job.code} value={job.code}>{job.title}</option>)}</select><input type="password" inputMode="numeric" maxLength={4} value={tempPin} onChange={(e) => setTempPin(e.target.value.replace(/\D/g, "").slice(0,4))} placeholder="임시 PIN 4자리" /><button disabled={busy || name.trim().length < 2 || tempPin.length !== 4} onClick={() => act("create-student", { name, number, jobCode, tempPin })}>학생 계정 만들기</button></div></article><article className="panel"><div className="panel-title"><div><span className="eyebrow">공고 템플릿</span><h2>이번 주에 추가</h2></div></div><div className="template-list">{(teacher.templates ?? []).slice(0,6).map((template) => <div key={template.id}><p><strong>{template.title}</strong><small>{template.world} · {template.reward}꿈</small></p><button disabled={busy || teacher.active_week.status !== "active"} onClick={() => act("open-template", { templateId: template.id })}>열기</button></div>)}</div></article>{teacher.seat_requests?.length ? <article className="panel"><div className="panel-title"><div><span className="eyebrow">자리 이동</span><h2>승인 대기</h2></div></div>{teacher.seat_requests.map((request) => <div className="review-row" key={request.id}><p><strong>{request.student_name} → {request.seat_name}</strong><small>{request.seat_type} · 이동비 {request.move_cost}꿈</small></p><button disabled={busy} onClick={() => act("review-seat", { requestId: request.id, decision: "approve" })}>승인</button><button className="subtle" disabled={busy} onClick={() => act("review-seat", { requestId: request.id, decision: "reject" })}>반려</button></div>)}</article> : null}</div>;
}

function TeacherExceptionActions({ teacher, busy, act }: { teacher: TeacherData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  if (!teacher.exceptions.length) return null;
  return <article className="panel exception-actions"><div className="panel-title"><div><span className="eyebrow red">확인 필요</span><h2>처리한 예외 정리</h2></div></div>{teacher.exceptions.map((exception) => <div key={exception.id}><p><strong>{exception.title}</strong><small>{exception.student_name ? `${exception.student_name} · ` : ""}{exception.detail}</small></p><button disabled={busy} onClick={() => act("resolve-exception", { exceptionId: exception.id })}>확인 완료</button></div>)}</article>;
}

function CustomTemplateList({ teacher, busy, act }: { teacher: TeacherData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const custom = teacher.templates.filter((template) => template.custom);
  if (!custom.length) return null;
  return <article className="panel custom-templates"><div className="panel-title"><div><span className="eyebrow">우리 반 공고</span><h2>직접 만든 템플릿</h2></div></div>{custom.map((template) => <div key={template.id}><p><strong>{template.title}</strong><small>{template.world} · {template.reward}꿈 · {template.duration_minutes}분</small></p><button disabled={busy || teacher.active_week.status !== "active"} onClick={() => act("open-template", { templateId: template.id })}>이번 주 열기</button></div>)}</article>;
}

function TeacherAdminPanels({ teacher, busy, act }: { teacher: TeacherData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const [className, setClassName] = useState(teacher.class_name); const [grade, setGrade] = useState(teacher.grade ?? 6); const [section, setSection] = useState(teacher.section ?? 1);
  const [goal, setGoal] = useState({ title: teacher.community_goal?.title ?? "", description: teacher.community_goal?.description ?? "", target: teacher.community_goal?.target_amount ?? 10000, minDonations: teacher.community_goal?.min_donations ?? 2 });
  const firstTemplate = teacher.templates?.[0]; const [template, setTemplate] = useState({ title: "", description: "", worldKey: firstTemplate?.world_key ?? "help", capacity: 2, reward: 300, duration: 30, submissionMethod: "활동 내용과 결과물 사진", repeatable: false });
  const [relatedJobs, setRelatedJobs] = useState<string[]>([]); const [rewards, setRewards] = useState<Record<string, number>>({ self_management: 1, knowledge_information: 1 });
  const worldOptions = Array.from(new Map((teacher.templates ?? []).filter((item) => item.world_key).map((item) => [item.world_key!, item.world])).entries());
  const toggleJob = (code: string) => setRelatedJobs((current) => current.includes(code) ? current.filter((item) => item !== code) : [...current, code]);
  return <section className="teacher-admin" aria-label="학급 세부 설정"><details className="panel manage-section" open><summary><span><small>학급 운영</small><strong>학급·급여·기본직업 설정</strong></span><b>펼치기</b></summary><div className="manage-body"><div className="teacher-form compact-form"><input value={className} onChange={(e) => setClassName(e.target.value)} aria-label="학급 이름" /><input type="number" min={1} max={6} value={grade} onChange={(e) => setGrade(Number(e.target.value))} aria-label="학년" /><input type="number" min={1} max={20} value={section} onChange={(e) => setSection(Number(e.target.value))} aria-label="반" /><button disabled={busy} onClick={() => act("update-class", { name: className, grade, section })}>학급 정보 저장</button></div><div className="salary-grid">{teacher.job_catalog.map((job) => <label key={job.code}><span><strong>{job.title}</strong><small>{job.world}</small></span><input type="number" min={100} max={5000} defaultValue={job.salary} aria-label={`${job.title} 월급`} onBlur={(e) => { const salary = Number(e.target.value); if (salary !== job.salary) void act("update-salary", { jobCode: job.code, salary }); }} /><b>꿈</b></label>)}</div><div className="assignment-list"><h3>학생 기본직업 배정</h3>{teacher.students.map((student) => { const current = teacher.job_catalog.find((job) => job.title === student.job); return <div key={student.id}><strong>{student.number}. {student.name}</strong><select defaultValue={current?.code ?? ""} onChange={(e) => { const job = teacher.job_catalog.find((item) => item.code === e.target.value); if (job) void act("assign-job", { studentId: student.id, jobCode: job.code, salary: job.salary }); }}><option value="" disabled>직업 선택</option>{teacher.job_catalog.map((job) => <option key={job.code} value={job.code}>{job.title}</option>)}</select></div>; })}</div></div></details><details className="panel manage-section"><summary><span><small>공동체와 공간</small><strong>공동체 목표·자리 설정</strong></span><b>펼치기</b></summary><div className="manage-body"><div className="goal-form"><input value={goal.title} onChange={(e) => setGoal({ ...goal, title: e.target.value })} placeholder="공동체 목표 이름" /><textarea value={goal.description} onChange={(e) => setGoal({ ...goal, description: e.target.value })} placeholder="달성하면 함께 무엇을 하나요?" /><label>목표 금액<input type="number" min={100} value={goal.target} onChange={(e) => setGoal({ ...goal, target: Number(e.target.value) })} /></label><label>학생별 최소 참여<input type="number" min={1} value={goal.minDonations} onChange={(e) => setGoal({ ...goal, minDonations: Number(e.target.value) })} /></label><button disabled={busy || goal.title.trim().length < 2 || goal.description.trim().length < 5} onClick={() => act("update-goal", goal)}>공동체 목표 저장</button></div><div className="seat-editor"><h3>자리별 특징과 비용</h3>{teacher.seat_catalog?.map((seat) => <SeatEditor key={seat.id} seat={seat} busy={busy} act={act} />)}</div></div></details><details className="panel manage-section"><summary><span><small>우리 반 공고</small><strong>새 공고 템플릿 만들기</strong></span><b>펼치기</b></summary><div className="manage-body template-builder"><input value={template.title} onChange={(e) => setTemplate({ ...template, title: e.target.value })} placeholder="공고 제목" /><textarea value={template.description} onChange={(e) => setTemplate({ ...template, description: e.target.value })} placeholder="학생이 실제 교실에서 할 일을 구체적으로 적어요." /><select value={template.worldKey} onChange={(e) => setTemplate({ ...template, worldKey: e.target.value })}>{worldOptions.map(([key, name]) => <option key={key} value={key}>{name}</option>)}</select><div className="job-checks">{teacher.job_catalog.map((job) => <label key={job.code}><input type="checkbox" checked={relatedJobs.includes(job.code)} onChange={() => toggleJob(job.code)} />{job.title}</label>)}</div><div className="template-numbers"><label>모집<input type="number" min={1} value={template.capacity} onChange={(e) => setTemplate({ ...template, capacity: Number(e.target.value) })} /></label><label>보수<input type="number" min={0} value={template.reward} onChange={(e) => setTemplate({ ...template, reward: Number(e.target.value) })} /></label><label>활동 시간<input type="number" min={5} value={template.duration} onChange={(e) => setTemplate({ ...template, duration: Number(e.target.value) })} /></label></div><input value={template.submissionMethod} onChange={(e) => setTemplate({ ...template, submissionMethod: e.target.value })} placeholder="제출 방법" /><div className="competency-scores">{Object.entries(competencyNames).map(([key, name]) => <label key={key}>{name}<select value={rewards[key] ?? 0} onChange={(e) => { const value = Number(e.target.value); setRewards((current) => { const next = { ...current }; if (value) next[key] = value; else delete next[key]; return next; }); }}>{[0,1,2,3,4,5].map((value) => <option key={value} value={value}>{value ? `+${value}` : "없음"}</option>)}</select></label>)}</div><label className="repeat-check"><input type="checkbox" checked={template.repeatable} onChange={(e) => setTemplate({ ...template, repeatable: e.target.checked })} />다른 주에도 반복 가능</label><button disabled={busy || template.title.trim().length < 3 || template.description.trim().length < 10 || !relatedJobs.length || !Object.keys(rewards).length} onClick={() => act("create-template", { ...template, relatedJobCodes: relatedJobs, competencyRewards: rewards })}>공고 템플릿 저장</button></div></details></section>;
}

function SeatEditor({ seat, busy, act }: { seat: TeacherData["seat_catalog"][number]; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const [value, setValue] = useState({ name: seat.name, type: seat.type, rent: seat.rent, moveCost: seat.move_cost, active: seat.active });
  return <div className="seat-edit-row"><span><strong>{seat.code}</strong><small>{seat.student_name ?? "빈자리"}</small></span><input value={value.name} onChange={(e) => setValue({ ...value, name: e.target.value })} aria-label={`${seat.code} 자리 이름`} /><input value={value.type} onChange={(e) => setValue({ ...value, type: e.target.value })} aria-label={`${seat.code} 자리 유형`} /><input type="number" min={0} value={value.rent} onChange={(e) => setValue({ ...value, rent: Number(e.target.value) })} aria-label={`${seat.code} 주거비`} /><input type="number" min={0} value={value.moveCost} onChange={(e) => setValue({ ...value, moveCost: Number(e.target.value) })} aria-label={`${seat.code} 이동비`} /><label><input type="checkbox" checked={value.active} onChange={(e) => setValue({ ...value, active: e.target.checked })} />사용</label><button disabled={busy} onClick={() => act("update-seat", { seatId: seat.id, ...value })}>저장</button></div>;
}

function TeacherEvidencePanel({ submissions, busy, act }: { submissions: TeacherJobSubmission[]; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void> }) {
  const [feedback, setFeedback] = useState<Record<string, string>>({});
  return <article className="panel teacher-evidence" id="teacher-evidence"><div className="panel-title"><div><span className="eyebrow">공고 활동 증거</span><h2>학생 제출 기록</h2><p>전체 승인 없이 필요할 때만 확인하거나 보완을 요청하세요.</p></div><span className="count-badge">{submissions.filter((item) => item.status === "completed").length}</span></div>{submissions.length ? <div className="evidence-list">{submissions.map((item) => { const completed = item.status === "completed"; const note = feedback[item.id] ?? ""; const imageEvidence = item.result_url?.startsWith("data:image/"); return <section className={`evidence-card ${item.evidence_review_status}`} key={item.id}><div className="evidence-card__head"><p><strong>{item.student_number}. {item.student_name}</strong><span>{item.posting_title}</span></p><b>{completed ? item.evidence_review_status === "revision_requested" ? "보완 요청 중" : item.evidence_review_status === "reviewed" ? "확인 완료" : "제출 완료" : item.status === "waitlisted" ? "대기 중" : "활동 중"}</b></div>{completed ? <><p className="evidence-summary">{item.summary}</p><div className="evidence-meta"><span>재미 {item.fun_rating ?? "-"}/5</span><span>어려움 {item.difficulty_rating ?? "-"}/5</span><span>{item.completed_at ? new Date(item.completed_at).toLocaleDateString("ko-KR") : ""}</span></div>{imageEvidence && item.result_url ? <Image className="evidence-image" src={item.result_url} alt={`${item.student_name} 학생의 ${item.posting_title} 결과물`} width={320} height={190} unoptimized /> : item.result_url ? <a className="evidence-link" href={item.result_url} target="_blank" rel="noreferrer">결과물 링크 열기 ↗</a> : <span className="evidence-none">첨부 결과물 없음</span>}{item.evidence_feedback ? <div className="revision-feedback"><strong>보완 내용</strong>{item.evidence_feedback}</div> : null}<div className="evidence-actions"><input aria-label={`${item.student_name} 보완 내용`} value={note} onChange={(e) => setFeedback((current) => ({ ...current, [item.id]: e.target.value.slice(0, 300) }))} placeholder="보완이 필요할 때만 내용을 적어요" /><button className="subtle" disabled={busy || item.evidence_review_status === "reviewed"} onClick={() => act("review-job-evidence", { applicationId: item.id, decision: "reviewed", feedback: "" })}>확인했어요</button><button disabled={busy || note.trim().length < 3} onClick={() => act("review-job-evidence", { applicationId: item.id, decision: "revision_requested", feedback: note })}>보완 요청</button></div></> : <p className="evidence-waiting">아직 활동 증거를 제출하지 않았어요.</p>}</section>; })}</div> : <p className="empty-copy">이번 주 공고 참여 기록이 아직 없습니다.</p>}</article>;
}

function TeacherDashboardContent({ teacher, busy, act, logout }: { teacher: TeacherData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void>; logout: () => void }) {
  const total = Math.max(1, teacher.stats.students); const participation = Math.round(teacher.stats.participating / total * 100); const goal = teacher.community_goal;
  return <div className="app teacher-mode"><div className="main-column teacher-column"><Topbar label={`${teacher.class_name} · 교사 관리`} onLogout={logout} /><main className="teacher-shell"><section className="teacher-welcome"><div><span className="eyebrow">학급코드 {teacher.class_code}</span><h1>{teacher.display_name}님, 필요한 것만<br /><em>한눈에</em> 살펴보세요.</h1><p>정상적인 일은 자동으로 처리하고 도움이 필요한 상황을 모아 보여드립니다.</p></div><div className="teacher-date"><span>현재 운영</span><strong>{teacher.active_week.week_number ? `${teacher.active_week.week_number}주차` : "시작 전"}</strong><small>{teacher.active_week.status === "active" ? "진행 중" : teacher.active_week.status === "settled" ? "정산 완료" : "공고 준비"}</small></div></section><section className="teacher-actions"><button className="primary" disabled={busy || teacher.active_week.status === "active"} onClick={() => act("start-week")}><span>▶</span><p><strong>이번 주 시작</strong><small>추천 공고 4개 자동 열기</small></p></button><button disabled={busy || teacher.active_week.status !== "active"} onClick={() => act("settle-week")}><span>✓</span><p><strong>이번 주 정산</strong><small>급여·월세·기록 한 번에</small></p></button><button onClick={() => document.getElementById("teacher-postings")?.scrollIntoView({ behavior: "smooth" })}><span>✦</span><p><strong>공고 현황</strong><small>{teacher.postings.length}개 공고 확인</small></p></button><button className="alert-action" onClick={() => document.getElementById("teacher-exceptions")?.scrollIntoView({ behavior: "smooth" })}><span>!</span><p><strong>예외 확인</strong><small>{teacher.stats.exceptions}건 확인 필요</small></p><b>{teacher.stats.exceptions}</b></button></section><section className="teacher-stats"><article><span className="round-icon purple">♙</span><p>전체 학생<strong>{teacher.stats.students}명</strong><small>현재 학급 계정</small></p></article><article><span className="round-icon green">↗</span><p>공고 참여율<strong>{participation}%</strong><small>{teacher.stats.participating}명 참여</small></p></article><article><span className="round-icon orange">✓</span><p>완료 업무<strong>{teacher.stats.completed}건</strong><small>역량 자동 반영</small></p></article><article><span className="round-icon blue">♥</span><p>공동체기금<strong>{(goal.current_amount ?? 0).toLocaleString()}꿈</strong><small>목표 {(goal.target_amount ?? 0).toLocaleString()}꿈</small></p></article></section><div className="teacher-grid"><article className="panel" id="teacher-postings"><div className="panel-title"><div><span className="eyebrow">이번 주 공고</span><h2>진행 상황</h2></div></div>{teacher.postings.length ? teacher.postings.map((posting) => <div className="teacher-job" key={posting.id}><span className="job-icon violet">✦</span><p><strong>{posting.title}</strong><small>{posting.assigned}명 참여 · {posting.completed}명 완료</small></p><div className="mini-progress"><i style={{ width: `${posting.capacity ? Math.round(posting.completed/posting.capacity*100) : 0}%` }} /></div><b>{posting.completed}/{posting.capacity}</b></div>) : <p className="empty-copy">이번 주 시작을 누르면 공고가 열립니다.</p>}</article><article className="panel exceptions" id="teacher-exceptions"><div className="panel-title"><div><span className="eyebrow red">확인 필요</span><h2>예외 상황</h2></div><span className="count-badge">{teacher.exceptions.length}</span></div><div className="exception-list">{teacher.exceptions.length ? teacher.exceptions.map((exception) => <div key={exception.id}><span className="exception-icon red">!</span><p><strong>{exception.title}</strong><small>{exception.student_name ? `${exception.student_name} · ` : ""}{exception.detail}</small></p></div>) : <p className="empty-copy">지금은 확인할 예외가 없습니다.</p>}</div></article></div><TeacherEvidencePanel submissions={teacher.job_submissions ?? []} busy={busy} act={act} />{teacher.bank_requests.length ? <article className="panel bank-queue"><div className="panel-title"><div><span className="eyebrow">은행 예외 승인</span><h2>처리 대기</h2></div></div>{teacher.bank_requests.map((request) => <div className="review-row" key={request.id}><p><strong>{request.student_name}</strong><small>{request.request_type === "saving" ? "저축" : "출금"} {request.amount.toLocaleString()}꿈</small></p><button disabled={busy} onClick={() => act("review-bank", { requestId: request.id, decision: "approve" })}>승인</button><button className="subtle" disabled={busy} onClick={() => act("review-bank", { requestId: request.id, decision: "reject" })}>반려</button></div>)}</article> : null}<article className="panel student-overview"><div className="panel-title"><div><span className="eyebrow">학생 현황</span><h2>학급 전체 보기</h2></div></div><div className="student-table"><div className="student-table-head"><span>학생</span><span>기본직업</span><span>현금</span><span>저축</span><span>공고 완료</span></div>{teacher.students.map((student) => <div key={student.id}><strong>{student.number}. {student.name}</strong><span>{student.job ?? "배정 대기"}</span><span>{student.cash.toLocaleString()}꿈</span><span>{student.savings.toLocaleString()}꿈</span><span>{student.jobs_completed}건</span></div>)}</div></article></main></div></div>;
}

function TeacherDashboard(props: { teacher: TeacherData; busy: boolean; act: (action: string, extra?: Record<string, unknown>) => Promise<void>; logout: () => void }) {
  const { teacher } = props;
  const weekActive = teacher.active_week.status === "active";
  return <>{weekActive ? <aside className="week-running-banner" role="status"><span>✓</span><p><strong>{teacher.active_week.week_number}주차는 이미 시작됐어요.</strong><small>공고 {teacher.postings.length}개가 진행 중입니다. 다음 주는 이번 주 정산 후 시작할 수 있어요.</small></p></aside> : null}<TeacherDashboardContent {...props} /></>;
}

export default function Home() {
  const [student, setStudent] = useState<StudentData | null>(null); const [teacher, setTeacher] = useState<TeacherData | null>(null);
  const [checking, setChecking] = useState(true); const [busy, setBusy] = useState(false); const [active, setActive] = useState<StudentView>("home"); const [toast, setToast] = useState("");
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 3200); };
  useEffect(() => { Promise.all([fetch("/api/student", { cache: "no-store" }), fetch("/api/teacher", { cache: "no-store" })]).then(async ([studentResponse, teacherResponse]) => { if (studentResponse.ok) { const data = await studentResponse.json(); if (data.ok) setStudent(data.student); } else if (teacherResponse.ok) { const data = await teacherResponse.json(); if (data.ok) setTeacher(data.teacher); } }).finally(() => setChecking(false)); }, []);
  const studentAct = async (action: string, extra: Record<string, unknown> = {}) => { setBusy(true); try { const response = await fetch("/api/student", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, ...extra }) }); const result = await response.json(); if (!response.ok || !result.ok) { notify(result.message ?? "처리하지 못했어요."); return; } if (result.student) setStudent(result.student); notify(result.message ?? (action === "complete-task" ? "기본업무를 기록했어요." : "안전하게 반영했어요.")); } finally { setBusy(false); } };
  const teacherAct = async (action: string, extra: Record<string, unknown> = {}) => { setBusy(true); try { const response = await fetch("/api/teacher", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action, ...extra }) }); const result = await response.json(); if (!response.ok || !result.ok) { if (response.status === 401 || result.code === "SESSION_EXPIRED" || result.code === "NO_SESSION") { window.alert("교사 로그인이 만료됐어요. 다시 로그인해 주세요."); setTeacher(null); return; } notify(result.message ?? "처리하지 못했어요."); return; } if (result.teacher) setTeacher(result.teacher); notify(result.message ?? "학급 운영에 반영했어요."); } finally { setBusy(false); } };
  const logoutStudent = async () => { await fetch("/api/student", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "logout" }) }); setStudent(null); setActive("home"); };
  const logoutTeacher = async () => { await fetch("/api/teacher", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "logout" }) }); setTeacher(null); };
  const title = useMemo(() => nav.find((item) => item.id === active)?.label ?? "미래탐험대", [active]);
  if (checking) return <main className="session-loading"><Brand /><div className="loading-wave"><i /><i /><i /></div><p>학급 기록을 불러오고 있어요…</p></main>;
  if (teacher) return <><TeacherDashboard teacher={teacher} busy={busy} act={teacherAct} logout={logoutTeacher} /><div className="teacher-shell teacher-setup-shell"><TeacherExceptionActions teacher={teacher} busy={busy} act={teacherAct} /><TeacherSetupPanels teacher={teacher} busy={busy} act={teacherAct} /><CustomTemplateList teacher={teacher} busy={busy} act={teacherAct} /><TeacherAdminPanels teacher={teacher} busy={busy} act={teacherAct} /></div></>;
  if (!student) return <Login onStudent={setStudent} onTeacher={setTeacher} />;
  if (student.first_login) return <PinSetup student={student} onComplete={setStudent} />;
  const changeView = (view: StudentView) => { const item = nav.find((entry) => entry.id === view); if (item?.bankerOnly && student.basic_job !== "은행원") { notify("은행 업무는 은행원만 열 수 있어요."); return; } if (item?.feature && !student.feature_unlocks.includes(item.feature)) { notify(view === "jobs" ? "기본업무를 2회 기록하면 일자리 탐험이 열려요." : "아직 잠긴 항로예요. 경험을 조금 더 쌓아보세요."); return; } setActive(view); };
  return <div className="app"><Sidebar student={student} active={active} onChange={changeView} onLogout={logoutStudent} /><div className="main-column"><Topbar label={`${student.basic_job ?? "직업 탐험"} · ${title}`} /><main className="content">{active === "home" ? <HomeView student={student} busy={busy} act={studentAct} openJobs={() => setActive("jobs")} /> : active === "jobs" ? <JobsView student={student} busy={busy} act={studentAct} /> : active === "wallet" ? <WalletView student={student} busy={busy} act={studentAct} /> : active === "bank" ? <BankView student={student} busy={busy} act={studentAct} /> : active === "growth" ? <GrowthView student={student} busy={busy} act={studentAct} /> : <RoomView student={student} busy={busy} act={studentAct} />}</main><nav className="mobile-nav" aria-label="모바일 학생 메뉴">{studentNav(student).map((item) => { const locked = Boolean(item.feature && !student.feature_unlocks.includes(item.feature)); return <button key={item.id} className={`${active === item.id ? "active" : ""} ${locked ? "nav-locked" : ""}`} onClick={() => changeView(item.id)}><span>{locked ? "◌" : item.icon}</span>{item.label.split(" ")[0]}{item.id === "bank" && student.bank_queue.length ? <b>{student.bank_queue.length}</b> : null}</button>; })}</nav></div>{toast ? <div className="toast" role="status"><span>✓</span>{toast}</div> : null}</div>;
}
